We define the rank of a formula, $rk(\phi)$, inductively:
  \begin{itemize}
  \item when $\phi$ is a literal, $rk(\phi)=0$,
  \item $rk(\phi\wedge\psi)=rk(\phi\vee\psi)=\max\{rk(\phi),rk(\psi)\}+1$,
  \item $rk(\forall x\,\phi)=rk(\exists x\,\phi)=rk(\phi)+1$.
  \end{itemize}

Let $\phi$ be a formula. The \emph{parameterized form} of $\phi(X)$ is a formula $\phi'$ together with fresh free variables $Z_1,\ldots,Z_n$ and formulas $\psi_1,\ldots,\psi_n$ such that:
  \begin{itemize}
  \item each $\psi_i(y)$ is a formula of the form $y\in\mu zZ. \psi'_i$ with $\mu zZ.\psi'_i$ closed\footnote{The essential point is that $\psi'_i$ has no second-order free variables. It is easier, and costs us no generality, to assume it has no first-order free variables as well.}
  \item $\phi$ is $\phi'[Z_i\mapsto\psi_i]$,
  \item the substitution $\phi'[Z_i\mapsto \psi_i]$ is permissible,
  \item $\phi'$ does not contain any sub-formula of the form $y\in\mu zZ. \psi'$ where $\mu zZ. \psi'$ is closed.
  \end{itemize}

We extend the language $\mathcal{L}_\mu$ to languages $\mathcal{L}^1_\mu$ and $\mathcal{L}^2_\mu$ by adding new formulas as follows. 
  \begin{itemize}
  \item every $\mathcal{L}_\mu$ formula is a $\mathcal{L}^1_\mu$ formula,
  \item if $\Theta$ is a sequent of $\mathcal{L}_\mu$ formulas, $\epsilon$ is a $\mathfrak{T}$-position for some $\mathfrak{T}$, and $n\in\mu xX.\phi$ is a formula in $\Theta$ then $[\Theta]^{n\in\mu xX.\phi,\epsilon}$ is a $\mathcal{L}^{1}_\mu$ formula,
  \item if $\Theta$ is a sequent of $\mathcal{L}^1_\mu$ formulas, $\epsilon$ is a $\mathfrak{T}$-position for some $\mathfrak{T}$, and $n\in\mu xX.\phi$ is a formula in $\Theta$ then $[\Theta]^{n\in\mu xX.\phi,\epsilon}$ is a $\mathcal{L}^{2}_\mu$ formula.
  \end{itemize}

When $\epsilon$ is a $\mathfrak{T}$-position, we define $\Delta(\epsilon)$ by:
  \begin{itemize}
  \item $\Delta(\langle\rangle)=\emptyset$,
  \item $\Delta(\epsilon\iota)=\Delta_\iota(\mathcal{R}(\iota))$.
  \end{itemize}

Let $F$ be locally defined function from $\mathfrak{T}$ to $\mathfrak{T}'$ and let $d$ be a proof tree in $\mathfrak{T}$. We define a proof tree $\bar F(d)$ in $\mathfrak{T}'$ together with an auxiliary function $h:\operatorname{dom}(\bar F(d))\rightarrow \operatorname{dom}(F)$ by:
  \begin{itemize}
  \item $h(\langle\rangle)=\langle\rangle$,
  \item if $h(\sigma)$ is defined and $F(h(\sigma))$ is $\mathrm{Read}^{\mathfrak{T}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ then $\bar F(d)(\sigma)=\mathrm{Rep}$ and $h(\sigma\top)=h(\sigma)\ulcorner d(\epsilon)\urcorner$,
  \item if $h(\sigma)$ is defined and $F(h(\sigma))$ is any other rule then $\bar F(d)(\sigma)=F(h(\sigma))$ and, for each $\iota\in|\bar F(d)(\sigma)|$, $h(\sigma\iota)=h(\sigma)\iota$.
  \end{itemize}

\label{thm:locally_def_endsequent}
  Fix a formula $n\in\mu xX.\phi$. If $F$ is a locally defined function from $\mathfrak{T}$ to $\mathfrak{T}'$ and $d$ is a proof tree in $\mathfrak{T}$ then
  \[\Gamma(\bar F(d))\subseteq (\Gamma(F)\setminus\{[n\in\mu xX.\phi]^{n\in\mu xX.\phi,\langle\rangle}\})\cup (\Gamma(d)\setminus\{n\in\mu xX.\phi\}).\]

\label{thm:substitution}
  For any formula $\psi(y)$ with only the free variable $y$, there is proof tree $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}$ in $\mathsf{ID}^{\infty}_{1,<0}$ with conclusion
  \[[n\in \mu xX.\phi]^{n\in\mu xX.\phi,\langle\rangle},\psi(n),\exists y\,\phi(y,\psi)\wedge{\sim}\psi(y).\]

We construct $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma)$ by induction on $\sigma$.  We take $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}(\langle\rangle)$ to be $\mathrm{Read}^{\mathsf{ID}_1^{\infty,+}}_{[n\in\mu xX.\phi]^{n\in\mu xX.\phi,\langle\rangle}}$.

  Suppose that $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}(\sigma)=\mathrm{Read}^{\mathsf{ID}_1^{\infty,+}}_{[\theta(\mu xX.\phi)]^{n\in\mu xX.\phi,\iota}}$. Consider the rule $\mathcal{R}(\theta(\mu xX.\phi))$; it must be an instance of one of the rules $\wedge \mathrm{I}$, $\vee \mathrm{I}^L$, $\vee\mathrm{I}^R$, $\omega$, $\exists\mathrm{I}$, or $\mathrm{Cl}$. If this rule is anything other than $\mathrm{Cl}$ then there is a corresponding rule $\mathcal{R}(\theta(\psi))$, so we set $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}(\sigma\top)=\mathcal{R}(\theta(\psi))$ and, for each $\iota'\in|\mathcal{R}(\theta(\psi))|=|\mathcal{R}(\theta(\mu xX.\phi))|$, $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}(\sigma\top)=\mathrm{Read}^{\mathsf{ID}_1^{\infty,+}}_{[\theta_{\iota'}(\mu xX.\phi)]^{n\in\mu xX.\phi,\iota'}}$.











If $\mathcal{R}$ is Cl$_{k\in \mu xX. \phi}$ then we take $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\mathcal{R})$ to be

\AxiomC{$\vdots$}
\noLine
\UnaryInfC{$[\Theta_\sigma[Z\mapsto\mu xX.\phi],\phi(k,\mu xX.\phi)]^{n\in\mu xX.\phi,\epsilon\top},\Theta_\sigma[Z\mapsto\psi],\phi(k,\psi) ,\exists x\, \phi(x,\psi)\wedge{\sim}\psi(x)$}
\LeftLabel{\scriptsize{$\mathrm{Read}^{\mathsf{ID}^{\infty,+}_1}_{[\Theta'_{\sigma\top L}]^{n\in\mu xX.\phi, \epsilon\top} }$}}
\UnaryInfC{$[\Theta_\sigma[Z\mapsto\mu xX.\phi]]^{n\in\mu xX.\phi,\epsilon},\Theta_\sigma[Z\mapsto\psi],\phi(k,\psi) ,\exists x\, \phi(x,\psi)\wedge{\sim}\psi(x)$}
\AxiomC{$d_{\psi(k)}$}
\noLine
\UnaryInfC{$\vdots$}
\noLine
\UnaryInfC{$\psi(k),{\sim}\psi(k)$}
\LeftLabel{I$\wedge$}
\BinaryInfC{$[\Theta_\sigma[Z\mapsto\mu xX.\phi]]^{n\in\mu xX.\phi,\epsilon},\Theta_\sigma[Z\mapsto\psi],\exists x\, \phi(x,\psi)\wedge{\sim}\psi(x),\phi(k,\psi)\wedge{\sim}\psi(k)$}
\LeftLabel{I$\exists$}
\UnaryInfC{$[\Theta_\sigma[Z\mapsto\mu xX.\phi]]^{n\in\mu xX.\phi,\epsilon},\Theta_\sigma[Z\mapsto\psi],\exists x\, \phi(x,\psi)\wedge{\sim}\psi(x)$}
\DisplayProof

\bigskip

and set $\Theta_{\sigma\top L}=\Theta_\sigma\cup\{\eta_\top\}$ (where $\eta_\top$ is $\phi(k,\psi)$ by definition). (Note that $\psi(k)$ is, again by definition, contained in $\Theta_\sigma[Z\mapsto\psi]$.)

We proceed by induction on $d$. If $d$ is $\mathrm{Def}_\phi$ then $\phi[x_i\mapsto m_i]$ is a true quantifier-free formula whose only atomic formulas have the form $\dot{R}t_1\cdots t_n$, and therefore there is a proof of $\phi[x_i\mapsto m_i]$ even in $\mathsf{ID}_{1}^{\infty,+}$.

  If $d$ is $\mathrm{Ax}_\eta$ then either $\eta[x_i\mapsto m_i]$ has the form $\dot{R}t_1\cdots t_n$, in which case $\mathrm{True}_{\eta[x_i\mapsto m_i]}$ suffices, or $\eta[x_i\mapsto m_i]$ has the form $n\in\mu xX.\phi$, in which case the deduction $d_{n\in\mu xX.\phi}$ is given above.  When the final inference rule of $d$ is $\wedge$I, $\vee$I, $\exists$I, $\mathrm{Cl}$, or $\mathrm{Cut}$, the claim follows immediately from the inductive hypothesis. (In the case of $\exists$I and $\mathrm{Cut}$, the premises may have additional free variables; we substitute these free variables with $0$'s to apply the inductive hypothesis.)

  When the final inference rule of $d$ is $\forall^y_{\forall x\,\phi}$I, we have a premise $d'$ concluding $\Gamma(d),\phi(y)$ where $y$ is not free in $\Gamma(d)$. For each $n$, the inductive hypothesis gives a deduction of $(\Gamma(d),\phi(n))[x_i\mapsto m_i]$, and we may apply an $\omega$ rule to obtain the desired deduction.

  When $d$ is $\mathrm{Ind}^t_{\forall x\,\phi}$, we let $n$ be $\overline{t[x_i\mapsto m_i]}$ and proceed by induction on $n$. For notational convenience, let $\phi'$ be $\phi[x_i\mapsto m_i]$. When $n=0$, we may apply the previous lemma to obtain a deduction $d^\infty_0$ with $\Gamma(d^\infty_0)\subseteq \phi'(0),{\sim}\phi(0)$. So suppose we have a deduction $d^\infty_n$ with $\Gamma(d^\infty_n)\subseteq {\sim}\phi'(0), \exists x\,\phi'(x)\wedge{\sim}\phi'(Sx)\, \phi'(n)$. Then we may take $d^\infty_{n+1}$ to be

  \AxiomC{$d^\infty_n$}
  \noLine
  \UnaryInfC{$\vdots$}
  \noLine
  \UnaryInfC{$ {\sim}\phi'(0), \exists x\,\phi'(x)\wedge{\sim}\phi'(Sx), \phi'(n)$}
  \AxiomC{$d_{\phi'(n+1)}$}
  \noLine
  \UnaryInfC{$\vdots$}
  \noLine
  \UnaryInfC{${\sim}\phi'(n+1),\phi'(n+1)$}
  \BinaryInfC{$ {\sim}\phi'(0), \exists x\,\phi'(x)\wedge{\sim}\phi'(Sx), \phi'(n)\wedge{\sim}\phi'(n+1), \phi'(n+1)$}
  \UnaryInfC{$ {\sim}\phi'(0), \exists x\,\phi'(x)\wedge{\sim}\phi'(Sx),\phi'(n+1)$}
  \DisplayProof

  The novel case is when $d$ is $\mathrm{Ind}^t_{\mu xX\, \phi,\psi(y)}$. Again, let us write $\phi'$ for $\phi[x_i\mapsto m_i]$, $t'$ for $t[x_i\mapsto m_i]$, and $\psi'$ for $\psi[x_i\mapsto m_i]$. In this case we may use an $\Omega^\flat$ inference rule applied to the function $\mathrm{Subst}^{t'\in \mu xX.\phi'\mapsto \psi'}$ from the previous lemma.

When $d$ is a proof tree in $\mathsf{ID}_1^{\infty}$, an \emph{ordinal bound above $\gamma$} on $d$ is a function $o^d:\operatorname{dom}(d)\rightarrow \mathrm{OT}$ such that
  \begin{itemize}
  \item for all $\sigma\in\operatorname{dom}(d)$, if $v_{n\in\mu xX.\phi,\epsilon}\in FV(o^d(\sigma))$ then $[\Theta]^{n\in\mu xX.\phi,\epsilon}\in\Gamma(d,\sigma)$ for some $\Theta$,
  \item if $\sigma\sqsubset\tau$ then $o^d(\tau)\ll_\gamma o^d(\sigma)$.
  \end{itemize}

  We say $d$ \emph{is bounded by $\alpha$ above $\gamma$} if there is an ordinal bound above $\gamma$, $o^d$, with $o^d(\langle\rangle)\operatorname{\underline{\ll}}_\gamma\alpha$.

\begin{enumerate}
  \item   Let $\eta$ be an atomic formula of the form $\dot{R}m_1\cdots m_n$ and let $\phi\in\{\sigma,\neg\sigma\}$ be false. If $d$ is a $\mathsf{ID}^\infty_{<\omega,0}$ proof tree then $\phi\not\in\Gamma(d)$.
  \item   For any formulas $\phi_L,\phi_R$ with rank $\leq n$ and $i\in\{L,R\}$ and any $\mathsf{ID}^\infty_{c,<n}$ proof tree $d$ with bound $\alpha$, there is a $\mathsf{ID}^\infty_{c,<n}$ proof tree $\mathrm{Inverse}^\wedge_{\phi_L,\phi_R,i}(d)$ with $\Gamma(\mathrm{Inverse}^\wedge_{\phi_L,\phi_R,i}(d))\subseteq(\Gamma(d)\setminus\{\phi_L\wedge\phi_R\})\cup\{\phi_i\}$ and bounded by $\alpha$.
  \item   For any formula $\phi(y)$ with rank $\leq n$ whose only free variable is $\phi$, any $m\in\mathbb{N}$, and any $\mathsf{ID}^\infty_{c,<n}$ proof tree $d$ with bound $\alpha$, there is a $\mathsf{ID}^\infty_{c,<n}$ proof tree $\mathrm{Inverse}^\forall_{\phi(y),m}(d)$ with $\Gamma(\mathrm{Inverse}^\forall_{\phi(y),m}(d))\subseteq(\Gamma(d)\setminus \{\forall x\,\phi(x)\})\cup\{\phi(m)\}$ and bounded by $\alpha$
  \item   For any formulas $\phi_L,\phi_R$ with rank $\leq n$ and any $\mathsf{ID}^\infty_{c,<n}$ proof trees $d_\wedge$ and $d_\vee$ bounded by $\alpha,\beta$ respectively, there is a $\mathsf{ID}^\infty_{c,<n}$ proof tree $\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)$ with $\Gamma(\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge))\subseteq (\Gamma(d_\wedge)\setminus\{\phi_L\wedge\phi_R\})\cup(\Gamma(d_\vee)\setminus\{{\sim}\phi_L\vee{\sim}\phi_R\})$ and bounded by $\alpha\# \beta$.
  \item   For any formula $\phi(y)$ with rank $\leq n$ and any $\mathsf{ID}^\infty_{c,<n}$ proof trees $d_\forall$ and $d_\exists$ bounded by $\alpha,\beta$ respectively, there is a $\mathsf{ID}^\infty_{c,<n}$ proof tree $\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall)$ with $\Gamma(\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall))\subseteq (\Gamma(d_\wedge)\setminus\{\forall x\,\phi(x)\})\cup(\Gamma(d_\vee)\setminus\{\exists x\,{\sim}\phi(x))$ and bounded by $\alpha\#\beta$.
  \item For any atomic formula of the form $n\in\mu xX.\phi$ with depth $\leq c$ and $\mathsf{ID}_{c,<0}^{\infty}$ proof trees $d_\mu$ and $d_\neg$ bounded by $\alpha,\beta$ respectively, there is a $\mathsf{ID}_{c,<0}^\infty$ proof tree $\mathrm{Elim}^{\mu}_{n\in\mu xX.\phi}(d_\mu,d_\neg)$ with $\Gamma(\mathrm{Elim}^{\mu}_{n\in\mu xX.\phi}(d_\mu,d_\neg))\subseteq(\Gamma(d_\mu)\setminus\{n\in \mu xX.\phi\})\cup(\Gamma(d_\neg)\setminus\{n\not\in\mu xX.\phi\})$ and bounded by $\alpha\#\beta$. \label{case_elim}
  \item If $d$ is a proof tree in $\mathsf{ID}_{c,<n+1}^{\infty}$ bounded by $\alpha$ then there is a proof tree $\mathrm{Reduce}_n(d)$ in $\mathsf{ID}_{c,<n}^\infty$ with $\Gamma(\mathrm{Reduce}_n(d))\subseteq\Gamma(d)$ and bounded by $\omega^\alpha$.
  \end{enumerate}

\ 
  \begin{itemize}
  \item $\mathsf{ID}_0^{\infty,+}$ is the arithmetic part: the theory containing True, $\mathrm{Cut}$ for formulas of depth $0$, $\wedge\mathrm{I}$, $\vee^L\mathrm{I}$, $\vee^R\mathrm{I}$, $\omega$, $\exists\mathrm{I}$, $\mathrm{Cl}$, and Rep for closed proper formulas of depth either $<C_0$ in $[\underline{\mathtt{\Omega}},C_0)$,
\item $\mathsf{ID}_{c+1}^{\infty,+}$ extends $\mathsf{ID}_c^{\infty,+}$ by
  \begin{itemize}
  \item $\mathrm{Cut}$ for formulas of depth $c+1$,
  \item $\Omega^\flat_{n\not\in\mu xX.\phi}$ where $\mu xX.\phi$ has depth $c+1$,
  \item $\mathrm{Read}^{\mathsf{ID}_{0,<0}^\infty}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ rules where $\phi$ has depth $c$ and $\Theta\subseteq\mathcal{L}_\mu$,
  \end{itemize}
\item $\mathsf{ID}_{\underline{\mathtt{\Omega}}}^{\infty,+}=\mathsf{ID}_{C_0-1}^{\infty,+}$,
\item $\mathsf{ID}^{\infty}_{\underline{\mathtt{\Omega}}}$ extends $\mathsf{ID}_{C_0-1}^{\infty,+}\cup\mathsf{ID}_{\underline{\mathtt{\Omega}}+C_0-1}^{\infty,+}$ by
  \begin{itemize}
  \item $\Omega^\flat_{n\not\in\mu xX.\phi}$ and $\mathrm{Cut}\Omega^\flat_{n\not\in\mu xX.\phi}$ where $\mu xX.\phi$ has depth $\underline{\mathtt{\Omega}}$,
  \item $\mathrm{Read}^{\mathsf{ID}_{\underline{\mathtt{\Omega}}+C_0-1,<0}^{\infty,+}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ rules where $\mu xX.\phi$ has depth $\underline{\mathtt{\Omega}}$ and $\Theta\subseteq\mathcal{L}^1_\mu$. 
  \end{itemize}
\item for $c$ a successor, $\mathsf{ID}_c^\infty$ extends $\mathsf{ID}_{c-1}^\infty\cup \mathsf{ID}_c^{\infty,+}$ by $\mathrm{Cut}\Omega^\flat_{n\not\in\mu xX.\phi}$ where $\phi$ has depth $c-1$.
\end{itemize}

\label{thm:substitution3}
  For any formula $\psi(y)$ with only the free variable $y$ and $\mu xX.\phi$ of depth $\underline{\mathtt{\Omega}}$ such that $\phi(\psi)$ has depth $<\underline{\mathtt{\Omega}}+C_0$, there is a proof tree $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}$ in $\mathsf{ID}^\infty_{\underline{\mathtt{\Omega}}+C_0-1}$ with conclusion
  \[[n\in \mu xX.\phi]^{n\in\mu xX.\phi,\langle\rangle},\psi(n),\exists y\,\phi(y,\psi)\wedge{\sim}\psi(y).\]

When $d$ is a proof tree in $\mathsf{ID}^\infty_c$ with conclusion $\Gamma$ and $\gamma$ is an ordinal term, an \emph{ordinal bound above $\gamma$ on $d$} is a function $o^d:\operatorname{dom}(d)\rightarrow \mathrm{OT}_{C_0+\Xi+C_0}$ such that:
  \begin{itemize}
  \item for all $\sigma\in\operatorname{dom}(d)$, if $v_{n\in\mu xX.\phi,\epsilon}\in \mathrm{FV}(o^d(\sigma))$ then $[\Theta]^{n\in\mu xX.\phi,\epsilon}\in\Gamma(d,\sigma)$ for some $\Theta$,
  \item for all $\sigma\in\operatorname{dom}(d)$, if $v_{\mu xX.\phi}\in \mathrm{FV}(o^d(\sigma))$ then some $m\not\in\mu xX.\phi$ appears as a subformula of an element of $\Gamma(d,\sigma)$
  \item if $\sigma\sqsubset\tau$ then $o^d(\tau)\ll_\gamma o^d(\sigma)$.
  \end{itemize}
